//Get country code and language
pm.test("Extract country and languageCode from URL query parameters", function () {
    // Get the request URL
    var requestUrl = pm.request.url.toString();

    // Use a regular expression to extract 'country' and 'languageCode' from the URL
    var countryMatch = requestUrl.match(/[?&]country=([a-zA-Z]+)/);
    var languageCodeMatch = requestUrl.match(/[?&]languageCode=([a-zA-Z]+)/);

    // Extract values (if matches found)
    var country = countryMatch ? countryMatch[1] : null;
    var languageCode = languageCodeMatch ? languageCodeMatch[1] : null;

    // Log the extracted values to the console
    console.log("Extracted Country from URL:", country);
    console.log("Extracted Language Code from URL:", languageCode);

    // Check if country and languageCode are defined and not null
    pm.expect(country, 'Country should not be null').to.not.be.null;
    pm.expect(languageCode, 'LanguageCode should not be null').to.not.be.null;

    // Optionally, check if they are non-empty strings
    pm.expect(country, 'Country should be a non-empty string').to.not.be.empty;
    pm.expect(languageCode, 'LanguageCode should be a non-empty string').to.not.be.empty;
});
//check any duplicates are present
pm.test("Check for duplicate article ", function ()  {
    // Get the response body as JSON
    var response = pm.response.json();

    var articles = {};
    var duplicates = [];

    // Loop through each article in the response
    response.Tiles.forEach(function (article) {
        var articleTitle = article.Title;

        // If the article title already exists in the object, mark it as a duplicate
        if (articles[articleTitle]) {
            duplicates.push(articleTitle);
        } else {
            articles[articleTitle] = true;
        }
    });

    // Check if duplicates were found
    if (duplicates.length > 0) {
        pm.expect(duplicates.length).to.be.greaterThan(0); // Fail the test if duplicates are found
        console.log('Duplicate article Titles:', duplicates);
    } else {
        console.log('No duplicates found');
        pm.expect(duplicates.length).to.be.equal(0);  // Pass the test if no duplicates
    }
});
//check, actual, expected,missing  articles articles
pm.test("Check if all expected titles are in the API response", function () {
    // Define the expected titles
    var expectedTitles = [ "DAZN 1","DAZN 2","DAZN RISE","DAZN FAST+", "Eurosport 1","Eurosport 2","NFL Network: Live 24/7 Coverage", "SPORTDIGITAL FUSSBALL", "Red Bull TV","MLB Network", "Unbeaten", "Rally TV", "NHL FAST Channel","DFB.TV"];

    // Parse the response JSON
    var response = pm.response.json();

    // Extract the titles from the API response
    var actualTitles = response.Tiles.map(function(tile) {
        return tile.Title;
    });

    // Log the expected and actual titles for debugging
    console.log("Expected Titles: ", expectedTitles);
    console.log("Actual Titles: ", actualTitles);

    // Check if the expected titles are present in the actual titles
    var missingTitles = expectedTitles.filter(function(title) {
        return !actualTitles.includes(title);
    });

    // If there are missing titles, assert that the missing titles are listed
    if (missingTitles.length > 0) {
        console.log("Missing Titles: ", missingTitles);
        pm.expect(missingTitles).to.have.lengthOf(0, 'The following titles are missing: ' + missingTitles.join(', '));
    } else {
        pm.expect(missingTitles.length).to.eql(0, 'All expected titles are present.');
        console.log("No Missing Tiles");
    }

    // Check if there are any extra titles in the actual response
    var extraTitles = actualTitles.filter(function(title) {
        return !expectedTitles.includes(title);
    });

    // If there are extra titles, assert that the extra titles are listed
    if (extraTitles.length > 0) {
        console.log("Extra Titles: ", extraTitles);
        pm.expect(extraTitles).to.have.lengthOf(0, 'The following extra titles are present: ' + extraTitles.join(', '));
    } else {
        pm.expect(extraTitles.length).to.eql(0, 'No extra titles should be present.');
        console.log("No Extra Tiles were present");

    }
});

